500	+final class WeekendPackagePlan implements RatePlanPolicy {
501	+
502	+    private static final Map<RoomType, BigDecimal> PRICE_BY_ROOM_TYPE = Map.of(
503	+            RoomType.STANDARD, new BigDecimal("520.00"),
